/* make a group just like mtmp */
/**
 * C ref: makemon.c:79
 * @param {CPtr<struct monst>} mtmp
 * @param {CInt} x
 * @param {CInt} y
 * @param {CInt} n
 * @param {CUInt} mmflags
 */
function* m_initgrp(mtmp, x, y, n, mmflags) {
    let mm = cptr.alloc(4);
    let cnt = rnd(n);
    let mon;
    /* Tuning: cut down on swarming at low character levels [mrs] */
    cnt = (cnt /
            ((cptr.ldI32o(u, $you_ulevel) < 3)
                ? 4
                : ((cptr.ldI32o(u, $you_ulevel) < 5) ? 2 : 1))) | 0;
    if (!cnt)
        cnt++;

    cptr.stI16(mm, x);
    cptr.stI16o(mm, $nhcoord_y, y);
    while (cnt--) {
        if (peace_minded(cptr.ldPtro(mtmp, $monst_data)))
            continue;
        /* Don't create groups of peaceful monsters since they'll get
         * in our way.  If the monster has a percentage chance so some
         * are peaceful and some are not, the result will just be a
         * smaller group.
         */
        if ((yield* enexto_gpflags(
            mm,
            cptr.ldI16(mm),
            cptr.ldI16o(mm, $nhcoord_y),
            cptr.ldPtro(mtmp, $monst_data),
            mmflags
        ))) {
            mon = (yield* makemon(
                cptr.ldPtro(mtmp, $monst_data),
                cptr.ldI16(mm),
                cptr.ldI16o(mm, $nhcoord_y),
                Number(BigInt.asUintN(32, (BigInt(mmflags >>> 0) | 8192n)))
            ));
            if (mon) {
                cptr.stI32o(mon, $monst_mpeaceful, 0);
                cptr.stI32o(mon, $monst_mavenge, 0);
                set_malign(mon);
                /* Undo the second peace_minded() check in makemon(); if the
                 * monster turned out to be peaceful the first time we
                 * didn't create it at all; we don't want a second check.
                 */
            }
        }
    }
}

